import type { ImageLoaderProps } from 'next/image';

/** Widths generated by scripts/optimize-images.mjs for /images/<name>-<width>.webp. */
const LOCAL_WIDTHS = [640, 1024, 1600];

/**
 * next/image loader. Sanity's CDN resizes CMS images; local photos are pre-resized at build
 * time. Next's own optimizer is never used.
 */
export default function imageLoader({ src, width, quality }: ImageLoaderProps) {
  const local = src.match(/^\/images\/(.+)-\d+\.webp$/);
  if (local) {
    const best = LOCAL_WIDTHS.find((w) => w >= width) ?? LOCAL_WIDTHS[LOCAL_WIDTHS.length - 1];
    return `/images/${local[1]}-${best}.webp`;
  }

  if (!src.startsWith('https://cdn.sanity.io/')) return src;

  // If the URL already has w and h (a crop for a given aspect ratio), keep the ratio.
  const url = new URL(src);
  const w = Number(url.searchParams.get('w'));
  const h = Number(url.searchParams.get('h'));
  if (w > 0 && h > 0) {
    url.searchParams.set('h', String(Math.round((width * h) / w)));
  }
  url.searchParams.set('w', String(width));
  url.searchParams.set('q', String(quality ?? 75));
  url.searchParams.set('auto', 'format');
  return url.toString();
}
